object Main {
  def main(args: Array[String]): Unit = {
    val line = scala.io.StdIn.readLine()
    val nama = line.trim.split("\\s+").filter(_.nonEmpty).toList
    val huruf = scala.io.StdIn.readLine()
    val jumlah = nama.filter(_.contains(huruf)).length
    println(jumlah)
  }
}
